Here's an example of how the component might look:

```jsx
import React from 'react';

const Layout = ({ variant = 'full-width', children }) => {
  return (
    <div className={`w-full ${variant === 'centered' ? 'mx-auto max-w-7xl' : ''} py-4`}>
      {children}
    </div>
  );
};

export default Layout;
